R = []
R.append((7080625,
("Chapati de pollo tandoori", "Use las sobras de pollo cocido para preparar un delicioso almuerzo.", "2", "210 g",
 ["medio pimiento rojo, en rebanadas finas", "media cebolla morada, en rebanadas finas", "1 puñado de cilantro fresco, picado en trozos grandes", "jugo de media lima", "1 cucharada de yogur griego sin grasa", "1 cucharadita de pasta tandoori", "100 g de pollo cocido frío, picado", "2 chapatis (aprox. 60 g cada uno)", "2 puñados de hojas de ensalada mixtas"],
 ["Ponga en un tazón el pimiento rojo en rebanadas, la cebolla morada, el cilantro y el jugo de lima. Mezcle bien y reserve.", "Mientras tanto, en otro tazón, mezcle el yogur con la pasta tandoori y luego incorpore el pollo picado.", "Coloque los chapatis en una sartén seca precalentada a fuego medio durante 45 segundos por cada lado para calentarlos bien.", "Extienda los chapatis y reparta el pollo sobre la mitad de cada uno. Agregue las hojas de ensalada y cubra con la mezcla de pimiento rojo y cebolla.", "Enróllelos, doblando hacia adentro los lados, y disfrute."],
 ["La mezcla de yogur y pasta tandoori de esta receta le da la humedad de la mayonesa sin la grasa. Pruébela mezclada con papas cocidas para preparar una ensalada de papa picante.", "Elija chapatis sin grasa y no agregue más grasa al servir, si está cuidando su peso.", "Los chapatis se hacen con harina integral, por lo que tienen más fibra y son ideales para preparar una comida rápida. Puede rellenarlos con ensalada y aguacate, o usar sobras de cordero en lugar de pollo.", "Porciones de fruta/verdura por porción: 1"], []),
("خبز الشباتي بدجاج التندوري", "استخدم بقايا الدجاج المطهو لتحضير وجبة غداء رائعة.", "2", "210 غ",
 ["نصف حبة فلفل رومي أحمر، مقطعة شرائح رفيعة", "نصف حبة بصل أحمر، مقطعة شرائح رفيعة", "حفنة كزبرة خضراء طازجة، مفرومة خشنًا", "عصير نصف ليمونة خضراء (لايم)", "1 ملعقة كبيرة زبادي يوناني خالٍ من الدسم", "1 ملعقة صغيرة معجون تندوري", "100 غ دجاج مطهو بارد، مقطع", "2 رغيف شباتي (حوالي 60 غ لكل رغيف)", "2 حفنة أوراق سلطة مشكّلة"],
 ["ضع شرائح الفلفل الرومي الأحمر والبصل الأحمر والكزبرة وعصير الليمون الأخضر في وعاء. امزج جيدًا وضعه جانبًا.", "في هذه الأثناء، في وعاء آخر، اخلط الزبادي مع معجون التندوري ثم أضف الدجاج المقطع وحرّك.", "ضع أرغفة الشباتي في مقلاة جافة مسخّنة مسبقًا على نار متوسطة 45 ثانية لكل جانب لتسخينها جيدًا.", "افرد أرغفة الشباتي ووزّع الدجاج على نصف كل رغيف. أضف أوراق السلطة ثم غطّها بخليط الفلفل الرومي الأحمر والبصل.", "لفّها مع ثني الجوانب إلى الداخل واستمتع بها."],
 ["يمنحك خليط الزبادي ومعجون التندوري في هذه الوصفة رطوبة المايونيز دون دهون. جرّبه ممزوجًا بالبطاطس المطهوة لتحضير سلطة بطاطس حارة.", "اختر أرغفة شباتي خالية من الدهون ولا تضف دهونًا إضافية عند التقديم إذا كنت تراقب وزنك.", "يُحضَّر الشباتي من دقيق القمح الكامل لذلك فهو أغنى بالألياف ومناسب لتحضير وجبة سريعة. يمكنك حشوه بالسلطة والأفوكادو، أو استخدام بقايا لحم الضأن بدلًا من الدجاج.", "حصص الفاكهة/الخضار في الحصة الواحدة: 1"], [])))
R.append((7084341,
("Caponata", "Esta sabrosa receta apta para veganos está llena de color, textura y sabor. Ideal como guarnición o plato principal.", "6", "392 g",
 ["media cucharada de aceite de oliva", "3 cebollas moradas, picadas", "2 tallos de apio, picados", "2 calabacitas", "3 a 4 berenjenas, en cubos", "4 dientes de ajo, machacados", "1 lata de 400 g de tomates", "1 cucharadita de alcaparras", "1 cucharada de vinagre de vino blanco", "1 cucharada de puré de tomate", "20 g de pasas sultanas", "150 ml de agua", "una buena molida de pimienta negra", "25 g de albahaca, en trozos", "1 cucharada de piñones", "2 calabacitas", "2 cucharaditas de aceite de oliva"],
 ["Agregue el aceite a una olla grande. Añada las cebollas y revuelva a fuego medio de 4 a 5 minutos, hasta que estén suaves y empiecen a dorarse.", "Agregue el apio, las calabacitas y las berenjenas, y cocine de 4 a 5 minutos, revolviendo con frecuencia.", "Agregue todos los demás ingredientes, excepto los piñones y la albahaca. Mezcle y tape con una tapa que ajuste bien.", "Baje el fuego para que hierva suavemente y cocine 15 minutos, revolviendo con frecuencia.", "Agregue la mitad de la albahaca y los piñones. Cocine 1 minuto y pase a un platón. Cubra con la albahaca y los piñones restantes, y sirva con los espaguetis.", "Para preparar los espaguetis: Corte las calabacitas con un espiralizador, colóquelas en agua hirviendo 2 minutos, escúrralas, mézclelas con un poco de aceite de oliva y sirva."],
 ["Si no tiene un espiralizador, use un cuchillo afilado para cortar tiras largas y delgadas de la calabacita. Corte una rebanada a lo largo de cada una para obtener una base plana desde la cual trabajar y luego coloque el lado largo sobre la tabla para que quede estable al cortar el resto.", "Instrucciones para congelar: Descongele en el refrigerador o en el microondas y recaliente hasta que esté muy caliente por completo.", "El análisis nutricional anterior incluye los espaguetis de calabacita como sugerencia de presentación.", "Para convertirlo en un plato principal satisfactorio, sírvalo junto con una fuente de proteína, como pescado a la parrilla o al horno.", "Porciones de fruta/verdura por porción: 2"], []),
("كابوناتا", "وصفة لذيذة مناسبة للنباتيين، مليئة بالألوان والقوام والطعم. مثالية كطبق جانبي أو طبق رئيسي.", "6", "392 غ",
 ["نصف ملعقة كبيرة زيت زيتون", "3 حبات بصل أحمر، مفرومة", "2 ساق كرفس، مفرومة", "2 حبة كوسا", "3-4 حبات باذنجان، مقطعة مكعبات", "4 فصوص ثوم، مهروسة", "1 علبة 400 غ طماطم", "1 ملعقة صغيرة كبر (قبار)", "1 ملعقة كبيرة خل النبيذ الأبيض", "1 ملعقة كبيرة معجون طماطم", "20 غ زبيب سلطانا", "150 مل ماء", "رشة كبيرة من الفلفل الأسود المطحون", "25 غ ريحان، ممزّق", "1 ملعقة كبيرة صنوبر", "2 حبة كوسا", "2 ملعقة صغيرة زيت زيتون"],
 ["ضع الزيت في قدر كبير. أضف البصل وحرّك على نار متوسطة من 4 إلى 5 دقائق حتى يذبل ويبدأ لونه بالاحمرار.", "أضف الكرفس والكوسا والباذنجان واطبخ من 4 إلى 5 دقائق مع التحريك باستمرار.", "أضف جميع المكونات المتبقية ما عدا الصنوبر والريحان. امزج وغطِّ القدر بغطاء محكم.", "اخفض الحرارة لتغلي برفق واطبخ 15 دقيقة مع التحريك باستمرار.", "أضف نصف الريحان والصنوبر. اطبخ دقيقة واحدة وضعه في طبق التقديم. زيّنه بما تبقى من الريحان والصنوبر وقدّمه مع السباغيتي.", "لتحضير السباغيتي: قطّع الكوسا بآلة التقطيع الحلزوني، ثم ضعها في ماء يغلي دقيقتين، وصفّها وقلّبها في قليل من زيت الزيتون، ثم قدّمها."],
 ["إذا لم يكن لديك آلة تقطيع حلزونية، فاستخدم سكينًا حادة لقطع شرائح طويلة ورفيعة من الكوسا. اقطع شريحة على طول كل حبة لتحصل على قاعدة مسطحة تعمل عليها، ثم ضع الحافة الطويلة على اللوح لتثبت أثناء تقطيع بقيتها.", "تعليمات التجميد: أذبها في الثلاجة أو في الميكروويف ثم أعد تسخينها حتى تصبح ساخنة تمامًا من الداخل.", "يشمل التحليل الغذائي أعلاه سباغيتي الكوسا كاقتراح للتقديم.", "لتحويلها إلى وجبة رئيسية مشبعة، قدّمها مع مصدر للبروتين مثل السمك المشوي أو المخبوز.", "حصص الفاكهة/الخضار في الحصة الواحدة: 2"], [])))
R.append((7084429,
("Fideos con camarones", "Camarones picantes que son el complemento perfecto para fideos de arroz y espaguetis de calabacita, con verduras llenas de sabor cítrico.", "4", "358 g",
 ["250 g de brócoli, separado en ramitos", "2 cucharaditas de aceite de canola", "6 cebollitas de cambray, cortadas en aros", "1 pimiento rojo, en rebanadas", "2 cm de raíz de jengibre, rallada", "1 chile rojo pequeño, picado finamente", "3 dientes de ajo, machacados", "1 paquete de 120 g de camarones jumbo crudos", "100 ml de agua", "250 g de espaguetis de calabacita", "300 g de fideos de arroz listos para usar", "110 g de espinacas baby", "ralladura y jugo de 1 lima", "2 cucharaditas de salsa de soya reducida en sal"],
 ["Ponga el brócoli en un recipiente apto para microondas con 1 cucharadita de agua, cúbralo con plástico adherente, perfórelo y caliente a máxima potencia 1.5 minutos; luego reserve.", "Mientras tanto, caliente el aceite en una sartén antiadherente o en un wok; luego agregue las cebollitas y el pimiento. Cocine de 2 a 3 minutos a fuego alto, revolviendo constantemente.", "Después, agregue a la sartén el jengibre, el chile y el ajo y cocine 1 minuto.", "Agregue los camarones jumbo, el agua, los espaguetis de calabacita, los fideos y el brócoli reservado y mezcle bien. Tape y cocine 2 minutos.", "Agregue las espinacas, el jugo de lima, la ralladura y la salsa de soya y mezcle de nuevo.", "Tape y caliente otros 2 a 3 minutos.", "Asegúrese de que el platillo esté caliente por completo y de que los camarones estén rosados; sirva de inmediato."],
 ["Pruebe agregar salmón u otro pescado en lugar de camarones.", "Para una versión vegetariana o vegana, use champiñones o tofu en lugar de camarones.", "Porciones de fruta/verdura por porción: 2"], []),
("نودلز بالجمبري", "يشكّل الجمبري الحار إضافة مثالية لنودلز الأرز وسباغيتي الكوسا، مع خضار منعشة بنكهة الحمضيات.", "4", "358 غ",
 ["250 غ بروكلي، مقسّم إلى زهيرات", "2 ملعقة صغيرة زيت اللفت (الكانولا)", "6 حبات بصل أخضر، مقطعة حلقات", "1 حبة فلفل رومي أحمر، مقطعة شرائح", "2 سم جذر زنجبيل، مبشور", "1 حبة فلفل أحمر حار صغيرة، مفرومة ناعمًا", "3 فصوص ثوم، مهروسة", "1 عبوة 120 غ جمبري ملكي نيئ", "100 مل ماء", "250 غ سباغيتي الكوسا", "300 غ نودلز أرز جاهز للاستخدام", "110 غ سبانخ صغيرة الأوراق", "قشر مبشور وعصير 1 ليمونة خضراء (لايم)", "2 ملعقة صغيرة صلصة الصويا قليلة الملح"],
 ["ضع البروكلي في وعاء صالح للميكروويف مع ملعقة صغيرة من الماء، وغطّه بغلاف بلاستيكي، ثم اثقبه وسخّنه على أعلى قدرة 1.5 دقيقة، ثم ضعه جانبًا.", "في هذه الأثناء، سخّن الزيت في مقلاة غير لاصقة أو وعاء ووك، ثم أضف البصل الأخضر والفلفل الرومي. اطبخ من 2 إلى 3 دقائق على نار عالية مع التحريك المستمر.", "بعد ذلك، أضف الزنجبيل والفلفل الحار والثوم إلى المقلاة واطبخ دقيقة واحدة.", "أضف الجمبري الملكي والماء وسباغيتي الكوسا والنودلز والبروكلي المحفوظ وامزج جيدًا. ضع الغطاء واطبخ دقيقتين.", "أضف السبانخ وعصير الليمون الأخضر والقشر المبشور وصلصة الصويا وامزج مرة أخرى.", "غطِّ وسخّن 2 إلى 3 دقائق أخرى.", "تأكد من أن الطبق ساخن من الداخل وأن الجمبري صار ورديًا، ثم قدّمه فورًا."],
 ["جرّب إضافة السلمون أو سمك آخر بدلًا من الجمبري.", "للحصول على نسخة نباتية، استخدم الفطر أو التوفو بدلًا من الجمبري.", "حصص الفاكهة/الخضار في الحصة الواحدة: 2"], [])))
R.append((7084875,
("Salmón y espárragos con salsa de berro", "Este platillo primaveral combina salmón fresco, con un delicioso toque de zumaque, y una maravillosa salsa de berro para crear una comida rápida y sencilla que todos disfrutarán. Esta receta fue seleccionada en colaboración con Slimming World.", "4", "465 g",
 ["700 g de papas nuevas, cortadas por la mitad o en cuartos si son grandes", "4 filetes de salmón sin piel y sin espinas (aprox. 480 g)", "2 cucharaditas de zumaque (vea el consejo)", "aceite en aerosol bajo en calorías", "200 g de espárragos delgados, sin los extremos duros", "200 g de chícharos chinos (vainas)", "ralladura y jugo de 1 limón sin cera", "80 g de berro", "150 g de yogur griego natural sin grasa ni azúcar", "1 paquete pequeño de albahaca fresca"],
 ["Precaliente el horno a 200 °C (180 °C con ventilador, gas 6).", "Ponga las papas nuevas en una olla con agua hirviendo a fuego alto y cocine de 18 a 20 minutos, o hasta que estén suaves.", "Mientras tanto, coloque los filetes de salmón en una bandeja antiadherente para hornear y espolvoréelos con el zumaque. Rocíe con un par de pulsaciones de aceite en aerosol bajo en calorías y hornee 15 minutos, o hasta que estén bien cocidos.", "Para preparar la salsa, ponga el berro, el yogur y casi toda la albahaca en el procesador de alimentos, procese hasta obtener una mezcla suave y sazone con un poco de pimienta (o use una batidora de inmersión y una jarra).", "Rocíe una sartén antiadherente o una plancha acanalada con un par de pulsaciones de aceite en aerosol bajo en calorías y colóquela a fuego alto. Agregue los espárragos y los chícharos chinos y cocine unos 2 minutos, o hasta que estén chamuscados pero todavía un poco firmes.", "Escurra las papas y aplástelas ligeramente con un tenedor; luego mézclelas con los chícharos chinos, los espárragos, el jugo de limón y casi toda la ralladura de limón. Reparta en los platos, cubra con el salmón (puede dejarlo entero o desmenuzarlo en trozos) y rocíe con la salsa de berro. Esparza el resto de las hojas de albahaca y la ralladura de limón para servir."],
 ["El zumaque es una especia de Oriente Medio que se vende en la mayoría de los supermercados grandes. Si no la encuentra, sustitúyala por un poco más de ralladura de limón.", "Revise las mezclas de especias o condimentos para ver si tienen ingredientes añadidos como azúcar, sal, harina o aceite. Si es posible, elija mezclas hechas solo con hierbas y especias.", "Use un yogur natural de su elección. Sin embargo, esto cambiará la información nutricional y la textura del platillo.", "Porciones de fruta/verdura por porción: 1"], []),
("سلمون وهليون مع صلصة الجرجير", "يجمع هذا الطبق الربيعي بين السلمون الطازج بلمسة منعشة من السماق وصلصة الجرجير الرائعة لتحضير وجبة سريعة وبسيطة يستمتع بها الجميع. تم اختيار هذه الوصفة بالتعاون مع Slimming World.", "4", "465 غ",
 ["700 غ بطاطس صغيرة جديدة، مقسومة نصفين أو أرباعًا إذا كانت كبيرة", "4 شرائح سلمون منزوعة الجلد والعظم (حوالي 480 غ)", "2 ملعقة صغيرة سماق (انظر النصيحة)", "بخاخ طهي قليل السعرات", "200 غ سيقان هليون رفيعة، تُكسر أطرافها الخشبية", "200 غ بازلاء سكرية (مانجتو)", "قشر وعصير 1 ليمونة غير مشمّعة", "80 غ جرجير", "150 غ زبادي يوناني طبيعي خالٍ من الدسم وغير محلّى", "1 عبوة صغيرة ريحان طازج"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية (180° مئوية مع المروحة، علامة الغاز 6).", "ضع البطاطس الجديدة في قدر ماء يغلي على نار عالية واطبخها من 18 إلى 20 دقيقة أو حتى تنضج.", "في هذه الأثناء، ضع شرائح السلمون في صينية خَبز غير لاصقة ورشّها بالسماق. رشّها بدفعتين من بخاخ الطهي قليل السعرات واخبزها في الفرن 15 دقيقة أو حتى تنضج تمامًا.", "لتحضير الصلصة، ضع الجرجير والزبادي ومعظم الريحان في محضّر الطعام واخلطها حتى تصبح ناعمة وتبّلها بقليل من الفلفل (أو استخدم خلاطًا يدويًا ووعاءً).", "رشّ مقلاة غير لاصقة أو مقلاة شواء بدفعتين من بخاخ الطهي قليل السعرات وضعها على نار عالية. أضف الهليون والبازلاء السكرية واطبخها نحو دقيقتين أو حتى تتفحّم قليلًا مع بقاء قوامها متماسكًا نوعًا ما.", "صفِّ البطاطس واهرسها برفق بالشوكة، ثم قلّبها مع البازلاء السكرية والهليون وعصير الليمون ومعظم قشر الليمون. وزّعها على الأطباق، وضع السلمون فوقها (يمكنك تركه كاملًا أو تفتيته إلى قطع) ورشّ صلصة الجرجير. انثر باقي أوراق الريحان وقشر الليمون عند التقديم."],
 ["السماق بهار شرق أوسطي متوفر في معظم المتاجر الكبرى. وإذا لم تجده، فاستبدله بقليل إضافي من قشر الليمون.", "تحقق من خلطات البهارات/التوابل لمعرفة ما إذا كانت تحتوي على مكونات مضافة مثل السكر أو الملح أو الدقيق أو الزيت. اختر خلطات مصنوعة من الأعشاب والبهارات فقط إن أمكن.", "استخدم زبادي طبيعيًا من اختيارك. غير أن ذلك سيغيّر المعلومات الغذائية وقوام الطبق.", "حصص الفاكهة/الخضار في الحصة الواحدة: 1"], [])))
R.append((7090941,
("Pastel de limón y polenta glaseado", "Este pastel de limón, ácido y glaseado, no contiene gluten y es fácil de preparar.", "8", "47 g",
 ["2 cucharaditas de extracto de limón", "jugo y ralladura fina de 1 limón", "3 cucharadas de edulcorante granulado", "2 huevos, batidos", "50 ml de aceite de canola (y 1 cucharadita para engrasar un molde para pan de 1 libra)", "50 ml de agua", "100 g de polenta instantánea", "1 cucharadita de bicarbonato de sodio", "jugo y ralladura fina de 1 limón", "1 cucharada de edulcorante granulado", "1 cucharada postre de miel"],
 ["Precaliente el horno a 180 ° (gas 4).", "Engrase el molde para pan y resérvelo listo para usar.", "En un tazón, agregue el extracto de limón, el jugo y la ralladura de 1 limón, el edulcorante, los huevos y el aceite, y bata bien.", "Incorpore el agua y bata de nuevo hasta que esté espumoso; incorpore suavemente la polenta y el bicarbonato de sodio, vierta de inmediato en el molde y hornee de 20 a 25 minutos.", "Saque el pastel del horno y deje enfriar 20 minutos.", "Mientras tanto, ponga el jugo y la ralladura de limón restantes en una olla pequeña con el edulcorante y caliente suavemente 1 minuto; agregue la miel y caliente de 1 a 2 minutos más hasta que adquiera consistencia de almíbar.", "Rocíe la miel con limón caliente sobre el pastel ya frío y deje que se empape unos minutos antes de servir."],
 ["Este pastel queda maravilloso con limas o naranjas en lugar de limón (reduzca el edulcorante si usa naranjas dulces).", "Es excelente servido con frutos rojos frescos y una cucharada de yogur estilo griego sin azúcar.", "Instrucciones para congelar: Corte en rebanadas y envuelva en papel aluminio para congelar (así podrá usar las rebanadas según las necesite). Puede desmoronarse un poco al descongelarse, pero seguirá sabiendo delicioso."], []),
("كيك الليمون والبولينتا اللزج بالشراب", "كيك الليمون هذا حامض لزج وخالٍ من الغلوتين وسهل التحضير.", "8", "47 غ",
 ["2 ملعقة صغيرة مستخلص الليمون", "عصير وقشر مبشور ناعمًا من 1 ليمونة", "3 ملعقة كبيرة محلّي محبّب", "2 بيضة، مخفوقة", "50 مل زيت اللفت (الكانولا) (وملعقة صغيرة واحدة لدهن قالب خبز بحجم رطل واحد)", "50 مل ماء", "100 غ بولينتا سريعة التحضير", "1 ملعقة صغيرة بيكربونات الصودا", "عصير وقشر مبشور ناعمًا من 1 ليمونة", "1 ملعقة كبيرة محلّي محبّب", "1 ملعقة حلويات عسل"],
 ["سخّن الفرن مسبقًا إلى 180° (علامة الغاز 4).", "ادهن قالب الخبز بالزيت وضعه جانبًا جاهزًا للاستخدام.", "في وعاء، أضف مستخلص الليمون وعصير وقشر ليمونة واحدة والمحلّي والبيض والزيت ثم اخفقها جيدًا معًا.", "أضف الماء واخفق مرة أخرى حتى يصبح الخليط رغويًا، ثم أضف البولينتا وبيكربونات الصودا وحرّك برفق، وضعه فورًا في قالب الخبز واخبزه من 20 إلى 25 دقيقة.", "أخرج الكيك من الفرن واتركه يبرد 20 دقيقة.", "في هذه الأثناء، ضع باقي عصير الليمون وقشره في قدر صغير مع المحلّي وسخّنه برفق دقيقة واحدة، ثم أضف العسل وسخّنه من دقيقة إلى دقيقتين إضافيتين حتى يصبح بقوام الشراب.", "اسكب العسل والليمون الساخنين فوق الكيك البارد واتركه ينقع بضع دقائق قبل التقديم."],
 ["هذا الكيك رائع مع الليمون الأخضر أو البرتقال بدلًا من الليمون (قلّل المحلّي عند استخدام البرتقال الحلو).", "رائع عند تقديمه مع التوت الطازج وملعقة من الزبادي على الطريقة اليونانية غير المحلّى.", "تعليمات التجميد: قطّعه إلى شرائح ثم لفّه بورق الألمنيوم للتجميد (يمكنك بعد ذلك استخدام الشرائح عند الحاجة). قد يتفتت قليلًا عند إذابته، لكنه سيبقى لذيذ الطعم."], [])))
